test('real core gets one scan per held keyboard press and a fresh scan after release', (t) => {
  const recipes = structuredClone(CLASSES);
  recipes[0].cooldown = 0.25;
  const match = createDuel(level, { classId: 'scout', classRecipes: recipes }),
    f = fixture(t);
  resumeDuel(match);
  f.key('KeyQ');
  const events = [];
  for (let tick = 0; tick < 100; tick++) {
    if (tick % 2 === 0) f.input.poll();
    stepDuel(match, f.input.consume());
    events.push(...match.runs[0].events);
  }
  assert.equal(events.filter((e) => e.type === 'ability.used').length, 1);
  f.up('KeyQ');
  f.key('KeyQ');
  f.input.poll();
  stepDuel(match, f.input.consume());
  assert.equal(match.runs[0].events.filter((e) => e.type === 'ability.used').length, 1);
});

test('shared-radio seats reach both couch gameplay commands without cross-control', (t) => {
  const pad = {
    index: 0,
    id: 'TX15 Joystick (Vendor: 1209 Product: 4f54)',
    mapping: '',
    connected: true,
    axes: Array(8).fill(0),
    buttons: Array.from({ length: 24 }, () => ({ value: 0 })),
  };
  const session = createControllerSession({ eventTarget: null });
  t.after(() => session.dispose());
  session.sample([pad]);
  session.split(0, [tx15StickProfile(pad), tx15StickProfile(pad, 'left')]);
  const f = fixture(t, { controllerSession: session });
  session.sample([pad], { active: true });
  f.input.poll();
  pad.axes[0] = 1;
  session.sample([pad], { active: true });
  let commands = f.input.poll();
  assert.equal(commands[0].direction, 'right');
  assert.equal(commands[1].direction, null);
  pad.axes[2] = 1;
  session.sample([pad], { active: true });
  commands = f.input.poll();
  assert.equal(commands[1].direction, 'up');
});

test('neutral Resume tick defers fresh local requests independently without releasing held pads', (t) => {
  const f = fixture(t),
    pad = makePad(0);
  f.setPads([pad]);
  f.input.poll();
  pad.buttons[0].pressed = true;
  f.resume();
  f.input.poll();
  assert.deepEqual(f.input.consume({ neutralActions: true }), neutralPair());
  assert.deepEqual(f.input.consume(), neutralPair(), 'A pad held through Resume is still blocked.');
  pad.buttons[0].pressed = false;
  f.input.poll();
  f.key('KeyQ');
  f.up('KeyQ');
  f.down(1, 'pickup', 7);
  f.lift(1, 'pickup', 7);
  f.input.poll();
  assert.deepEqual(f.input.consume({ neutralActions: true }), neutralPair());
  assert.deepEqual(
    f.input.consume().map((c) => [c.action, c.pickup]),
    [
      [true, false],
      [false, true],
    ],
  );
  assert.deepEqual(f.input.consume(), neutralPair(), 'Local requests emit one pulse each.');
  pad.buttons[0].pressed = true;
  f.input.poll();
  assert.deepEqual(f.input.consume({ neutralActions: true }), neutralPair());
  assert.equal(f.input.consume()[0].action, true);
  assert.equal(
    f.input.consume()[0].action,
    true,
    'Fresh controller input keeps its held semantics.',
  );
  pad.buttons[0].pressed = false;
  f.input.poll();
  f.input.consume();
  pad.buttons[0].pressed = true;
  pad.buttons[2].pressed = true;
  f.input.poll();
  assert.deepEqual(f.input.consume({ neutralActions: true }), neutralPair());
  pad.buttons[0].pressed = false;
  pad.buttons[2].pressed = false;
  f.input.poll();
  assert.deepEqual(
    f.input.consume().map((c) => [c.action, c.pickup]),
    [
      [true, true],
      [false, false],
    ],
    'An admitted short pad press survives release before the next poll.',
  );
  assert.deepEqual(f.input.consume(), neutralPair());
});

test('clearing a deferred Resume request retires it before the next fixed tick', (t) => {
  const f = fixture(t);
  f.key('KeyQ');
  f.down(1, 'pickup', 8);
  assert.deepEqual(f.input.consume({ neutralActions: true }), neutralPair());
  f.input.clearPlayer(0);
  assert.deepEqual(
    f.input.consume().map((c) => [c.action, c.pickup]),
    [
      [false, false],
      [false, true],
    ],
  );
  f.input.clearPhysical();
  assert.deepEqual(f.input.consume(), neutralPair());
});

